def _emit_whole_key_debug_event(direction: str, key_count: int) -> None:
    try:
        if not envs.VLLM_ASCEND_KVPOOL_RANGE_DEBUG:
            return
        payload = {
            "event": "whole_key",
            "direction": direction,
            "key_count": int(key_count),
